function canRun(){return clockPresentation(clockFlags()).canRun;}
function schedule(){stopClock();if(canRun())timer=setTimeout(async()=>{timer=null;try{await updateSavedLife(current=>advanceLife(current,data,1));if(state.phase!=='running'||pendingInjuryCare(state)||militaryObligation(state))fastForward=false;if(view==='game')render();}catch(error){paused=true;message(saveBlocked()?'다른 탭의 최신 기록을 확인해 주세요.':error?.message||'시간 진행을 잠시 멈췄습니다. 기록을 저장한 뒤 새로고침해주세요.');if(view==='game')render();}},fastForward?35:800/speed);}
function checkTransferRecovery(){const recovered=recoverSaveTransfer(saveStorage);if(recovered.recovered&&state){transferReloadRequired=true;paused=true;stopClock();transferRecoveryError='중단 전의 저장을 복구했습니다. 현재 화면의 기록은 파일로 보관한 뒤 새로고침하고 이전 삶 이어하기를 선택해 주세요.';throw new Error(transferRecoveryError);}transferRecoveryError=null;}
async function updateSavedLife(action,{nextPaused,nextSpeed}={}){if(saveBlocked())throw new Error('다른 탭의 최신 기록을 확인해 주세요.');if(!saveCoordinator)throw new Error('안전한 자동 저장을 준비하지 못했습니다.');try{return await saveCoordinator.run(({metadata})=>{checkTransferRecovery();const before=state,next=freezeSaveSnapshot(settleAutomaticReserve(action(before))),settings={paused:nextPaused??paused,speed:nextSpeed??speed};if(next&&!validSave(next))throw new Error('변경된 기록을 확인하지 못해 이전 기록을 유지합니다.');const raw=encodeSaveRecord({life:next,settings,saveMetadata:metadata});saveStorage.setItem(KEY,raw);if(saveStorage.getItem(KEY)!==raw)throw new Error('저장 기록을 확인하지 못했습니다. 진행 기록을 파일로 보관해 주세요.');state=next;paused=settings.paused;speed=settings.speed;storageIssue=false;storageQuotaBlocked=false;renderStorageCapacity();return{before,next};});}catch(error){if(error?.code==='SAVE_CONFLICT')showSaveConflict(error);else{handleStorageQuota(error);storageIssue=true;if(error?.recoveryRequired)transferRecoveryError=error.message;message(transferRecoveryError||error?.message||'');}throw error;}}
async function save(){if(saveBlocked())return false;try{await updateSavedLife(current=>current);return true;}catch{return false;}}

async function resumeLatest({forcePaused=false}={}){try{if(!saveCoordinator)throw new Error('안전한 저장을 준비하지 못했습니다. 새로고침 후 다시 시도해 주세요.');const saved=await saveCoordinator.adopt(()=>stored(),{recover:()=>recoverSaveTransfer(saveStorage)});if(!saved){message('저장된 기록을 읽지 못했습니다. 기록 파일과 백업을 확인해 주세요.');return;}transferRecoveryError=null;transferReloadRequired=false;hideSaveConflict();saveBrowser?.close();state=enableRefinements(enableContinuity(enableRemedies(enableEconomicLife(enableMarket(enableFormedFamily(normalizeMilitaryPath(enableHouseholdFinance(saved.life,data),data),data),data),data),data),data),data);paused=forcePaused||!!saved.settings.paused;fastForward=false;speed=[1,2,5].includes(saved.settings.speed)?saved.settings.speed:1;lastChanges=[];endingFeedLimit=80;if(!await save())return;message(saved.migrated?'이전 버전의 선택 기록을 보존해 이어왔습니다.':'최신 저장한 시점부터 삶이 이어집니다.');render();}catch(error){paused=true;stopClock();message(error?.message||'최신 저장을 확인하지 못했습니다.');}}

function stored(){try{const raw=saveStorage.getItem(KEY);if(raw){const s=decodeSaveRecord(raw),life=s.life||s;if(validSave(life))return {life,settings:s.settings||{}};}
 const old=saveStorage.getItem(OLD_KEY);if(old){const life=migrateSave(JSON.parse(old),data);if(life&&validSave(life))return {life,settings:{},migrated:true};}}catch{}return null;}
function show(id){const changed=view!==id;if(view!==id){focusDashboard?.close({silent:true});cancelPendingAssetOpen();debtBrowser?.close();}if(id!=='game'){decisionDialog.update(null);injuryDialog.update(null);militaryDutyBrowser?.close();}if(view!==id)familyBrowser?.close();view=id;for(const name of ['welcome','birth','game','ending'])$(name).hidden=name!==id;if(changed)focusScreen(document,id);}
const integer=n=>new Intl.NumberFormat('ko-KR').format(n);
function cityLabel(city){return city.sourceRegion&&city.sourceRegion!==city.name?`${city.sourceRegion} · ${city.name}`:city.name;}
function stopSpin(){spinToken++;birthReel.stop();}
function persistBirth(){try{saveStorage.setItem(BIRTH_KEY,JSON.stringify({seed:pendingBirth.seed,name:pendingBirth.name,city:pendingBirth.city,family:pendingBirth.family,dataVersion:data.version,weightVersion:data.birthCitySource.rawSha256}));}catch{storageIssue=true;message('');}}
function readBirth(){try{const raw=saveStorage.getItem(BIRTH_KEY);if(!raw)return null;const p=JSON.parse(raw);if(typeof p.seed!=='string'||!p.seed||p.seed.length>64||typeof p.name!=='string'||p.name.length>16||p.dataVersion!==data.version||(p.weightVersion??p.populationVersion)!==data.birthCitySource.rawSha256)throw new Error('pending');const city=drawBirthCity(p.seed,data);if(JSON.stringify(p.city)!==JSON.stringify(city))throw new Error('pending city');if(!p.name.trim()){p.name=suggestedName;try{saveStorage.setItem(BIRTH_KEY,JSON.stringify(p));}catch{storageIssue=true;}}const family=Object.hasOwn(p,'family')?p.family:generateBirthFamily(p.seed,city,data);if(!validBirthFamily(family,p.seed,city.id))throw new Error('pending family');return {...p,city,family};}catch{try{saveStorage.removeItem(BIRTH_KEY);}catch{}message('저장된 추첨 자료가 현재 자료와 달라 새로 추첨할 수 있습니다.');return null;}}
function revealBirth(){if(!pendingBirth)return;stopSpin();$('birth-name').textContent=`${pendingBirth.name}님의 첫 번째 주소`;const c=pendingBirth.city,profile=cityProfiles.get(c.id),current=currentAreaCaption(profile);$('birth-current-area').textContent=current;$('birth-current-area').hidden=!current;$('city-reel').setAttribute('aria-live','polite');$('city-reel').textContent=c.name;renderCityMap(c);$('birth-region').textContent=c.sourceRegion||c.region;$('birth').classList.add('revealed');$('birth').setAttribute('aria-busy','false');$('birth-probability').textContent=(c.probability*100).toLocaleString('ko-KR',{minimumFractionDigits:4,maximumFractionDigits:4})+'%';const info=birthPresentation(c,data.birthCitySource);$('birth-probability-label').textContent=info.probabilityLabel;$('birth-weight-label').textContent=info.weightLabel;$('birth-population').textContent=info.weightText;$('birth-source-date').textContent=info.periodText;$('birth-method').textContent=info.method;$('birth-features').textContent=profile.summary;persistBirth();$('birth-result').hidden=false;$('begin-life').disabled=!playEnvironment.supported;$('birth-redraw').disabled=!playEnvironment.supported;message('');focusBirthResult(document);}
function startBirthDraw({redraw=false}={}){if(!playEnvironment.supported)return;if(busy||(redraw&&(!pendingBirth||view!=='birth'||$('birth').getAttribute('aria-busy')==='true')))return;stopClock();if(pendingBirth&&!redraw){show('birth');void finishBirthDraw();window.scrollTo({top:0,behavior:'instant'});return;}busy=true;try{const seed=crypto.getRandomValues(new Uint32Array(2)).join('-'),name=redraw?pendingBirth.name:resolveLifeName($('name').value,suggestedName),city=drawBirthCity(seed,data);if(!city)throw new Error('cities');pendingBirth={seed,name,city,family:generateBirthFamily(seed,city,data)};$('birth-name').textContent=`${name}님의 첫 번째 주소`;persistBirth();stopSpin();show('birth');$('birth').classList.remove('revealed');$('birth').setAttribute('aria-busy','true');$('birth-result').hidden=true;$('city-map').style.visibility='hidden';$('city-reel').textContent='어디에서 태어날까요?';$('birth-current-area').hidden=true;$('city-reel').setAttribute('aria-live','off');$('begin-life').disabled=true;$('birth-redraw').disabled=true;$('birth-region').textContent='대한민국 어딘가에서';message('');window.scrollTo({top:0,behavior:'instant'});if(matchMedia('(prefers-reduced-motion: reduce)').matches){void finishBirthDraw();return;}birthReel.start(data.birthCities,Number(seed.split('-')[0])%data.birthCities.length,city);}catch{pendingBirth=null;show('welcome');message('출생도시를 추첨하지 못했습니다. 자료를 다시 불러와주세요.');}finally{busy=false;}}
async function startLife(){if(!playEnvironment.supported)return;if(saveBlocked()){showSaveConflict();return;}if(transferRecoveryError){message(transferRecoveryError);return;}if(busy||!pendingBirth||$('begin-life').disabled)return;busy=true;stopSpin();stopClock();try{const fresh=createLife(pendingBirth.seed,data,pendingBirth.name,{birthCity:pendingBirth.city,birthFamily:pendingBirth.family});if(!validSave(fresh))throw new Error('새 삶의 기록을 확인하지 못해 기존 기록을 유지합니다.');if(!saveCoordinator)throw new Error('안전한 저장을 준비하지 못했습니다.');const preview=inspectSaveText(JSON.stringify(fresh));const result=await saveCoordinator.run(({beforePrimary,metadata})=>{checkTransferRecovery();return commitSaveTransfer(saveStorage,preview,{confirmed:true,life:fresh,backupKey:PREVIOUS_BACKUP_KEY,settings:{paused:false,speed:1},saveMetadata:metadata,expectedPrimary:beforePrimary});});state=freezeSaveSnapshot(result.life);hideSaveConflict();storageQuotaBlocked=false;storageIssue=false;paused=false;fastForward=false;speed=1;feedLimit=16;moneyFeedLimit=16;endingFeedLimit=80;lastChanges=[];try{saveStorage.removeItem(BIRTH_KEY);}catch{}pendingBirth=null;renderStorageCapacity();message('새로운 삶이 시작되었습니다. 시간이 자동으로 흐르며, 갈림길에서는 선택을 기다립니다.');render();window.scrollTo({top:0,behavior:'instant'});}catch(error){if(error?.code==='SAVE_CONFLICT')showSaveConflict(error);else{handleStorageQuota(error);if(error?.recoveryRequired){transferRecoveryError=error.message;storageIssue=true;}message(error?.message||'추첨 결과를 확인하지 못했습니다. 새로고침 후 다시 확인해주세요.');}}finally{busy=false;}}
function residenceLabel(r){const city=data.birthCities?.find(c=>c.region===r.region&&c.name===r.city);if(city)return cityLabel(city);return ["특별시","광역시","특별자치시"].some(s=>r.city===r.region+s)?r.city:[r.region,r.city].filter(Boolean).join(" ");}
function ageText(s){return `${s.age}세 ${s.month||0}개월`;}
function itemText(node,text){node.textContent=displayCopy(text??'');}
function renderTags(node,items){node.replaceChildren();for(const text of displayLines(items)){const span=document.createElement(node.tagName==='UL'?'li':'span');span.textContent=text;node.append(span);}}
function renderFacts(node,items){node.replaceChildren();for(const text of displayLines(items)){const li=document.createElement('li');li.textContent=text;node.append(li);}}
function renderTimeline(node,events,reverse=false,channel='life',limit=Infinity){if(timelineFeedSeed!==state?.seed){timelineFeed.reset();timelineFeedSeed=state?.seed;}return timelineFeed.render(node,events,{reverse,channel,limit,groupRoutine:['life-feed','money-feed'].includes(node.id)});}
function netAssets(s){return s.cash-s.debt+(militarySavingsSummary(s)?.lockedPrincipalWan||0)+investmentSummary(s).totals.totalValueWan;}
function renderFinanceFacts(id,pairs){const list=$(id);list.replaceChildren();for(const[label,value]of pairs){const row=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;row.append(dt,dd);list.append(row);}}
function renderFinance(){
 const account=personalFinanceOverview(state);mobileDashboard.update({ageText:ageText(state),cashText:money(account.cashWan),livingText:money(account.monthlyLivingWan)});for(const [id,value]of [['cash-wallet',account.cashWan],['property-wallet',account.propertyWan],['investment-wallet',account.investmentWan],['debt-balance',account.debtWan],['income',account.annualSalaryWan]])itemText($(id),money(value));itemText($('living-cost'),`${money(account.monthlyLivingWan)} / 월`);const living=livingCostSummary(state),academyCurrent=['cadet','officer'].includes(state.academy?.status);$('military-info-open').hidden=!state.service.active&&!state.service.pay&&!state.service.savings&&!academyCurrent&&!state.serviceReview&&!state.reserveService&&!state.serviceDeferral;$('military-provided-note').hidden=!living.militaryProvided&&!living.academyProvided;$('military-provided-note').textContent=living.academyProvided?'사관학교 학비·숙식 지원':'복무 중 숙식 제공';
 $('military-career-summary').hidden=!academyCurrent;renderFinanceFacts('military-career-facts',academyCurrent?[['현재 역할',state.job.title],['현재 상태',state.academy.status==='cadet'?'사관학교 재학 중':'장교 경로']]:[]);
 for(const id of ['property-open-title','property-wallet','investment-open-title','investment-wallet'])$(id).disabled=pendingInjuryCare(state);$('property-wallet').setAttribute('aria-label',`부동산 ${money(account.propertyWan)}, 보유 내역 열기`);$('investment-wallet').setAttribute('aria-label',`주식·펀드 ${money(account.investmentWan)}, 보유 내역 열기`);
 const savings=militarySavingsSummary(state),pay=militaryPaySummary(state),facts=militaryFinanceView(pay,savings);
 $('military-pay-summary').hidden=!pay;renderFinanceFacts('military-pay-facts',facts.payFacts);
 $('military-payment').hidden=!facts.paymentFacts.length;renderFinanceFacts('military-payment-facts',facts.paymentFacts);
 $('military-savings-summary').hidden=!savings;renderFinanceFacts('military-account-facts',facts.accountFacts);
 $('military-settlement').hidden=!facts.settlementFacts.length;$('military-settlement-title').textContent=facts.settlementTitle;renderFinanceFacts('military-settlement-facts',facts.settlementFacts);renderServiceReview();
}
function renderServiceReview(){
 let panel=$('service-review-panel');if(!panel){panel=document.createElement('section');panel.id='service-review-panel';$('military-info').append(panel);}panel.replaceChildren();
 const review=state.serviceReview,deferral=serviceDeferralSummary(state),reserve=reserveSummary(state);panel.hidden=!review&&!deferral&&!reserve;if(panel.hidden)return;
 if(deferral){const copy=document.createElement('p');copy.textContent=deferral.legacyExpired?'입대 재검토 기간이 지난 기록입니다. 지난 일상과 복무 이력은 그대로 보관합니다.':deferral.status==='resolved'?'입대를 선택해 유예를 마쳤습니다.':deferral.status==='waiting-recovery'?'유예 24개월을 모두 사용했습니다. 회복을 마친 뒤 복무할 군을 선택합니다.':`대학 재학 기간 외 유예 ${deferral.outsideMonths}/24개월 · 남은 기간 ${deferral.remainingMonths}개월${deferral.collegeExcluded?' · 재학 중에는 유예 개월이 늘지 않습니다.':''}`;panel.append(copy);}
 if(reserve){const heading=document.createElement('h3'),copy=document.createElement('p'),list=document.createElement('ul');heading.textContent='예비군';copy.textContent=`${reserve.status}${reserve.currentYear>0&&reserve.currentYear<=8?' · '+reserve.currentYear+'년차':''}`;for(const row of reserve.years){const item=document.createElement('li');item.textContent=`${row.year}년차 · ${row.completedHours}/${row.requiredHours}시간 이수${row.postponedUntilMonth!==null&&row.completedHours<row.requiredHours?' · 회복 후 일정 재검토':''}`;list.append(item);}panel.append(heading,copy,list);if(state.phase!=='ended'){
 const label=document.createElement('label'),toggle=document.createElement('input'),caption=document.createElement('span'),help=document.createElement('p');
 label.className='reserve-auto-setting';toggle.type='checkbox';toggle.id='reserve-auto-enabled';toggle.checked=state.reserveAutomation?.enabled===true;toggle.disabled=saveBlocked()||state.phase!=='running'||pendingInjuryCare(state);caption.textContent='정상 예비군 훈련 자동 참여';label.append(toggle,caption);help.className='small';help.textContent='켜면 정상 훈련에 자동으로 참여합니다. 부상·연기된 일정은 직접 확인합니다.';
 toggle.addEventListener('change',()=>{if(busy||saveBlocked()){toggle.checked=state.reserveAutomation?.enabled===true;return;}const enabled=toggle.checked;employmentAction(()=>setReserveAutomation(state,enabled),'예비군 참여 설정을 저장했습니다.').catch(()=>renderServiceReview());});panel.append(label,help);
 }if(reserve.due){const button=document.createElement('button');button.type='button';button.className='secondary';button.textContent='예비군 훈련 선택하기';button.addEventListener('click',()=>{$('military-info').close();syncDecisionDialog();militaryDutyBrowser.reopen();});panel.append(button);}}
 if(!review)return;
 const p=document.createElement('p');p.textContent=serviceReviewMessage(state);panel.append(p);
 if(!['recovering','ready'].includes(review.status)||state.phase==='ended'||deferral?.legacyExpired)return;
 const check=serviceReadiness(state);for(const [branch,label]of [['army','육군'],['navy','해군'],['airforce','공군']]){const b=document.createElement('button');b.type='button';b.className='secondary';b.textContent=`${label} 복무 시작`;b.disabled=!check.eligible;b.addEventListener('click',()=>employmentAction(()=>enlistAfterRecovery(state,branch,data),'복무를 시작했습니다.').then(()=>$('military-info').close()).catch(error=>message(error.message)));panel.append(b);}
 if(deferral)return;
 const decline=document.createElement('button');decline.type='button';decline.className='quiet';decline.textContent='현재 일상 이어가기';decline.disabled=pendingInjuryCare(state)||state.phase!=='running';decline.addEventListener('click',()=>employmentAction(()=>declineDeferredService(state),'현재 일상을 이어갑니다.').then(()=>$('military-info').close()).catch(error=>message(error.message)));panel.append(decline);
}
function renderHealthHistory(id,summary){const host=$(id);host.replaceChildren();for(const event of lifeHealthHistory(summary)){const row=document.createElement('li'),when=document.createElement('span'),title=document.createElement('b'),facts=document.createElement('ul');when.textContent=event.when;title.textContent=event.title;renderFacts(facts,event.facts);row.append(when,title,facts);host.append(row);}}
function renderHealth(){const summary=lifeHealthSummary(state);$('health-status-panel').hidden=!summary||(!injuryImpact(state).active&&!summary.incidentHistory.length);renderFinanceFacts('health-status-facts',[...lifeHealthFacts(summary),...(injuryImpact(state).active?[['대응',state.lifeHealth.injury.care?.label||'선택 대기'],['근무',state.service.active?'군 월급 정상 지급':injuryImpact(state).workLabel],['취미',injuryImpact(state).severity==='critical'?'모든 취미 휴식':injuryImpact(state).severity==='major'?'신체 부담이 적은 실내 활동만':'가벼운 실내 활동만']]:[])]);renderHealthHistory('health-history-list',summary);$('health-history').hidden=!summary?.incidentHistory.length;}
function renderEndingHealth(){const summary=lifeHealthSummary(state),cause=lifeEndingReason(state.ending);$('ending-cause').textContent=cause;$('ending-cause').hidden=!cause;const savings=militarySavingsSummary(state),facts=militaryFinanceView(militaryPaySummary(state),savings),settlementFacts=savings?.settlement?.atMonth===state.totalMonths&&savings.settlement.reason==='death'?facts.settlementFacts:[];$('ending-health-panel').hidden=!summary?.incidentHistory.length&&!settlementFacts.length;renderHealthHistory('ending-health-history',summary);$('ending-service-settlement').hidden=!settlementFacts.length;renderFinanceFacts('ending-service-settlement-facts',settlementFacts);}

function summarizeChanges(before,after){const changes=[];for(const [key,label]of [['health','건강'],['joy','만족'],['learn','배움'],['bond','관계']]){const diff=Math.round((after[key]-before[key])*10)/10;if(diff)changes.push(`${label} ${diff>0?'+':''}${diff}`);}const net=netAssets(after)-netAssets(before);if(Math.abs(net)>.01)changes.push(`순자산 ${net>0?'+':''}${money(net)}`);if(before.job.title!==after.job.title)changes.push(`직업 ${before.job.title} → ${after.job.title}`);if(before.residence.region!==after.residence.region||before.residence.housing!==after.residence.housing)changes.push(`거주 ${before.residence.region} ${before.residence.housing} → ${after.residence.region} ${after.residence.housing}`);if(economicAnnualSalaryWan(before)!==economicAnnualSalaryWan(after))changes.push(`연수입 ${money(economicAnnualSalaryWan(before))} → ${money(economicAnnualSalaryWan(after))}`);if(before.education!==after.education)changes.push(`학업 ${after.education}`);for(const tag of after.status||[])if(!(before.status||[]).includes(tag))changes.push(`상태 ${tag}`);return changes;}
async function pick(index){if(saveBlocked()||busy||state?.phase!=='decision')return;busy=true;stopClock();try{let option;const {before,next}=await updateSavedLife(current=>{option=choicesFor(current,data)[index];return choose(current,index,data);});lastChanges=summarizeChanges(before,next);message(`${ageText(state)} · ${option[0]} — 선택 결과를 반영했습니다.`);render();}catch(error){paused=true;message(error?.message||'선택을 처리하지 못했습니다. 새로고침 후 이어하기를 선택해주세요.');render();}finally{busy=false;}}
